Abaixo está um componente React + TypeScript completo, com **autocomplete**, **dropdown virtualizado**, **ocultação sem matches** e **validação com borda vermelha**.

## Estrutura principal

```tsx
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useId,
  type FC,
  type ChangeEvent,
  type KeyboardEvent,
} from 'react';

// ---------------------------------------------------------------
// Tipos
// ---------------------------------------------------------------
type DropDownInput<S extends string = string> = FC<DropDownInputProps<S>>;

interface SelectOption<S extends string> {
  value: S;
  label: string;
  disabled?: boolean;
}

interface DropDownInputProps<S extends string> {
  options: SelectOption<S>[];
  placeholder?: string;
  defaultValue?: S;
  onChange?: (value: S) => void;
  onSelect?: (option: SelectOption<S>) => void;
  onClear?: () => void;
  minMatchChars?: number;                       // mínimo de caracteres para busca (default 2)
  validator?: (value: string) => boolean;       // validação extra opcional
  className?: string;
  inputClassName?: string;
  containerClassName?: string;
  listClassName?: string;
  rowHeight?: number;                           // altura por linha virtual (default 48)
  maxVirtualItems?: number;                     // limite de itens virtualizados (default 500)
  bufferCount?: number;                         // buffer de scroll (default 8)
  readOnly?: boolean;
  autoComplete?: string;
  autoFocus?: boolean;
  style?: React.CSSProperties;
  containerStyle?: React.CSSProperties;
  inputStyle?: React.CSSProperties;
  listStyle?: React.CSSProperties;
}

// ---------------------------------------------------------------
// Constantes e helpers
// ---------------------------------------------------------------
const DEFAULT_MIN_CHARS = 2;
const DEFAULT_ROW_HEIGHT = 48;
const DEFAULT_MAX_VIRTUAL = 500;
const DEFAULT_BUFFER = 8;

function mergeClasses(base: string[], extra?: string | string[]): string {
  return [...base, ...(extra?.split(' ') || [])].filter(Boolean).join(' ');
}

function filterOptions<S extends string>(
  options: SelectOption<S>[],
  query: string,
  minChars: number,
): SelectOption<S>[] {
  if (query.length < minChars) return [];
  const q = query.toLowerCase();
  return options.filter((o) => {
    if (o.disabled === true) return false;
    return (o.label as string).toLowerCase().includes(q);
  });
}

// ---------------------------------------------------------------
// Componente
// ---------------------------------------------------------------
function DropDownInput<S extends string>({
  options,
  placeholder,
  defaultValue,
  onChange,
  onSelect,
  onClear,
  minMatchChars = DEFAULT_MIN_CHARS,
  validator,
  className,
  inputClassName,
  containerClassName,
  listClassName,
  rowHeight,
  maxVirtualItems,
  bufferCount,
  readOnly = false,
  autoComplete = 'off',
  autoFocus,
  style,
  containerStyle,
  inputStyle,
  listStyle,
}: DropDownInputProps<S>) {
  const inputId = useId();
  const listboxId = `${inputId}-listbox`;

  // refs
  const inputRef = useRef<HTMLInputElement>(null!);
  const containerRef = useRef<HTMLDivElement>(null!);
  const listRef = useRef<HTMLDivElement | null>(null);
  const virtualEntriesRef = useRef<Map<number, RefObject<HTMLElement | null>>>(new Map());
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // estado
  const [localValue, setLocalValue] = useState<string>(defaultValue ?? '');
  const [selectedOption, setSelectedOption] = useState<SelectOption<S> | null>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [focusedIndex, setFocusedIndex] = useState<number | null>(null);

  const effectiveMinChars = useMemo(
    () => Math.max(1, minMatchChars ?? DEFAULT_MIN_CHARS),
    [minMatchChars],
  );

  // mapa rápido para checar valores exatos
  const valueIndexMap = useMemo(() => new Map<string, number>(), [options]);

  // opções que batem com o texto digitado
  const matches = useMemo(() => {
    const q = localValue.trim();
    if (q.length < effectiveMinChars) return [];
    return filterOptions(options, q, effectiveMinChars);
  }, [localValue, options, effectiveMinChars]);

  const hasExact = useMemo(() => valueIndexMap.has(localValue), [valueIndexMap, localValue]);

  // validação
  const validity = useMemo<boolean>(() => {
    if (selectedOption != null) return true;
    if (localValue === '') return true;
    if (hasExact) return true;
    if (validator != null && !validator(localValue)) return false;
    return matches.length > 0;
  }, [selectedOption, localValue, hasExact, matches, validator]);

  const errorText = useMemo(() => {
    if (validity) return '';
    if (localValue === '') return '';
    if (validator != null && !validator(localValue)) return 'Valor inválido.';
    return 'Nenhuma opção corresponde ao texto digitado.';
  }, [validity, localValue, validator]);

  const displayed = isOpen ? matches : [];

  // ---------------------------------------------------------------
  // Virtualização da lista + referências estáveis
  // ---------------------------------------------------------------
  useLayoutEffect(() => {
    const items = displayed.length;
    if (items === 0) {
      virtualEntriesRef.current.clear();
      listRef.current?.scrollTop = 0;
      return;
    }

    const rect = listRef.current?.getBoundingClientRect();
    if (!rect) {
      virtualEntriesRef.current.clear();
      return;
    }

    const row = rowHeight ?? DEFAULT_ROW_HEIGHT;
    const buffer = bufferCount ?? DEFAULT_BUFFER;
    const maxVisible = maxVirtualItems ?? DEFAULT_MAX_VIRTUAL;
    const total = items.length;
    const rows = Math.max(0, Math.floor(rect.height / row));
    let start = 0;
    const end = Math.min(total, rows + buffer + maxVisible);

    if (end > total) {
      start = total - end;
    } else if (start + end - 1 > total - rows + buffer) {
      start = Math.max(0, total - end + buffer);
    }

    let scrollTop = start * row;

    if (focusedIndex !== null) {
      const fi = Math.max(0, Math.min(focusedIndex, total - 1));
      if (fi >= start + rows) {
        // rola para trazer o item focado para cima
        const item = items[fi];
        const el = item.ref?.current as HTMLElement | null;
        if (el && listRef.current) {
          const ir = listRef.current.getBoundingClientRect();
          let targetTop = el.top + ir.top - el.height / 2;
          let s = targetTop - ir.top;
          const maxBottom = ir.height - el.height;
          s = Math.min(s, maxBottom);
          s = Math.max(0, s - buffer * row);
          const relTop = el.top - ir.top;
          let start2 = Math.max(0, Math.floor(relTop / row) - buffer);
          const rows2 = Math.max(0, Math.floor(ir.height / row));
          let end2 = Math.min(total, rows2 + buffer + maxVisible);
          let st = start2;
          if (end2 > total) st = total - end2;
          else if (st + end2 - 1 > total - rows2 + buffer)
            st = Math.max(0, total - end2 + buffer);
          start = st;
          scrollTop = start * row;
        }
      } else if (
        fi - start >= buffer || (start + rows) - 1 - fi >= buffer
      ) {
        // centro o item focado se estiver visível, mas deslocado
        const item = items[fi];
        const el = item.ref?.current as HTMLElement | null;
        if (el && listRef.current) {
          const ir = listRef.current.getBoundingClientRect();
          let targetTop = el.top + ir.top - el.height / 2;
          let s = targetTop - ir.top;
          const maxBottom = ir.height - el.height;
          s = Math.min(s, maxBottom);
          s = Math.max(0, s - buffer * row);
          const relTop = el.top - ir.top;
          let start2 = Math.max(0, Math.floor(relTop / row) - buffer);
          const rows2 = Math.max(0, Math.floor(ir.height / row));
          let end2 = Math.min(total, rows2 + buffer + maxVisible);
          let st = start2;
          if (end2 > total) st = total - end2;
          else if (st + end2 - 1 > total - rows2 + buffer)
            st = Math.max(0, total - end2 + buffer);
          start = st;
          scrollTop = start * row;
        }
      }
    }

    const visible = items.slice(start, Math.min(start + rows, total));
    const entries = new Map<number, RefObject<HTMLElement | null>>();
    visible.forEach((item, i) => {
      const idx = start + i;
      entries.set(idx, useRef(item.ref?.current ?? null));
    });
    virtualEntriesRef.current = entries;
    if (listRef.current) {
      listRef.current.scrollTop = scrollTop;
    }
  }, [
    displayed,
    rowHeight,
    bufferCount,
    maxVirtualItems,
    focusedIndex,
    listRef,
    row,
  ]);

  // ---------------------------------------------------------------
  // Alteração do texto
  // ---------------------------------------------------------------
  const handleChange = useCallback(
    (e: ChangeEvent<HTMLInputElement>) => {
      const next = e.target.value;
      if (next !== localValue) {
        // se estava selecionando um valor exato e o usuário apaga tudo, limpa a seleção
        if (
          selectedOption &&
          selectedOption.value === next &&
          next.length === 0
        ) {
          setSelectedOption(null);
          setFocusedIndex(null);
        }
        setLocalValue(next);
      }
      // evita processar filtro desnecessário a cada tecla
      clearTimeout(timerRef.current);
      timerRef.current = setTimeout(() => {}, 120);
    },
    [localValue, selectedOption],
  );

  // fechar manualmente: clique fora, Escape etc.
  const handleClose = useCallback(() => {
    setIsOpen(false);
    setFocusedIndex(null);
    if (selectedOption && selectedOption.value === localValue) {
      // fechamento acidental enquanto selecionado
      setSelectedOption(null);
      setLocalValue('');
      if (onChange) onChange('');
    } else if (selectedOption) {
      // restaura o valor da opção escolhida, mas deixa de “selecionada”
      const opt = matches.find((m) => m.value === selectedOption.value);
      if (opt) {
        setLocalValue(opt.value);
        setSelectedOption(null);
      } else {
        setSelectedOption(null);
      }
    }
  }, [selectedOption, localValue, matches, onChange]);

  // abrir o dropdown com clique no input
  const handleOpenClick = useCallback(() => {
    if (readOnly || matches.length === 0) return;
    inputRef.current?.focus();
    setIsOpen(true);
    if (focusedIndex == null) setFocusedIndex(0);
  }, [readOnly, matches.length, focusedIndex]);

  // selecionar uma opção
  const handleSelect = useCallback(
    (option: SelectOption<S>) => {
      setSelectedOption(option);
      setLocalValue(option.value);
      setFocusedIndex(-1); // será corrigido no próximo useLayoutEffect
      setIsOpen(false);
      if (onSelect) onSelect(option);
      if (onChange) onChange(option.value);
    },
    [onSelect, onChange],
  );

  // teclado
  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLInputElement>) => {
      if (readOnly) return;

      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        if (focusedIndex >= 0 && focusedIndex < displayed.length) {
          handleSelect(displayed[focusedIndex]);
        }
        return;
      }

      if (!isOpen) {
        if (e.key === 'ArrowDown' || e.key === 'Down') {
          e.preventDefault();
          if (matches.length > 0) {
            setIsOpen(true);
            setFocusedIndex(0);
          }
          return;
        }
        return;
      }

      const len = displayed.length;
      if (len === 0) {
        if (localValue.trim().length > 0) {
          setIsOpen(false);
          if (selectedOption && selectedOption.value === localValue) {
            setSelectedOption(null);
            setLocalValue('');
            if (onChange) onChange('');
          }
        }
        e.preventDefault();
        return;
      }

      switch (e.key) {
        case 'ArrowDown':
        case 'Down':
          e.preventDefault();
          const cur = focusedIndex ?? -1;
          if (cur < len - 1) setFocusedIndex(cur + 1);
          else setFocusedIndex(len - 1);
          break;
        case 'ArrowUp':
        case 'Up':
          e.preventDefault();
          const curUp = focusedIndex ?? len - 1;
          if (curUp > 0) setFocusedIndex(curUp - 1);
          else setFocusedIndex(0);
          break;
        case 'Home':
          e.preventDefault();
          setFocusedIndex(0);
          break;
        case 'End':
          e.preventDefault();
          setFocusedIndex(len - 1);
          break;
        case 'Escape':
          handleClose();
          break;
      }
    },
    [
      isOpen,
      focusedIndex,
      matches,
      displayed,
      localValue,
      selectedOption,
      handleClose,
      handleSelect,
      onChange,
      readOnly,
    ],
  );

  // ---------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------
  return (
    <div
      ref={containerRef}
      className={mergeClasses(['drop-down-input__container'], containerClassName)}
      style={containerStyle}
      tabIndex={0}
      onClick={handleOpenClick}
      onKeyDown={handleKeyDown}
    >
      <input
        ref={inputRef}
        className={mergeClasses(
          ['drop-down-input__input'],
          validity ? [] : ['is-invalid'],
          inputClassName,
        )}
        type="text"
        value={localValue}
        disabled={readOnly || options.every((o) => o.disabled === true)}
        placeholder={placeholder ?? 'Digite para buscar...'}
        autoComplete={autoComplete || 'off'}
        readOnly={readOnly}
        autoFocus={autoFocus}
        aria-autocomplete="list"
        aria-expanded={isOpen}
        aria-controls={listboxId}
        aria-labelledby={inputId}
        role="combobox"
        style={inputStyle}
      />
      <div
        id={listboxId}
        role="listbox"
        className={mergeClasses('drop-down-input__list', listClassName, listStyle ? [] : [])}
        style={listStyle}
        ref={listRef}
      >
        {Array.from(virtualEntriesRef.current.entries()).map(([index, ref]) => {
          const option = displayed[index];
          if (!option) return null;
          const isSelected = selectedOption?.value === option.value;
          const isActive = focusedIndex === index;
          return (
            <li key={index} style={{ height: rowHeight ?? DEFAULT_ROW_HEIGHT }}>
              <button
                role="option"
                aria-selected={isSelected}
                tabIndex={0}
                className={[
                  'drop-down-input__item',
                  isSelected ? 'drop-down-input__item--selected' : '',
                  isActive ? 'drop-down-input__item--focused' : '',
                ].filter(Boolean).join(' ']}
                onClick={() => handleSelect(option)}
                style={
                  listStyle
                    ? Object.assign({}, listStyle, { margin: 0, padding: 0 })
                    : undefined
                }
              >
                {option.label}
              </button>
            </li>
          );
        })}
      </div>
      {errorText && (
        <span className="drop-down-input__error" role="alert">
          {errorText}
        </span>
      )}
    </div>
  );
}

export default DropDownInput;
export type { DropDownInput, DropDownInputProps, SelectOption };
```

## Exemplo de uso

```tsx
import { useState } from 'react';
import { DropDownInput, type SelectOption } from './DropDownInput';

