import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useId,
  type FC,
  type ChangeEvent,
  type KeyboardEvent,
} from 'react';

// ---------------------------------------------------------------------------
// Tipos
// ---------------------------------------------------------------------------
type DropDownInput<S extends string = string> = FC<DropDownInputProps<S>>;

interface SelectOption<S extends string> {
  value: S;
  label: string;
  disabled?: boolean;
}

interface DropDownInputProps<S extends string> {
  options: SelectOption<S>[];
  placeholder?: string;
  defaultValue?: S;
  onChange?: (value: S) => void;
  onSelect?: (option: SelectOption<S>) => void;
  onClear?: () => void;
  minMatchChars?: number;                // default 2
  validator?: (value: string) => boolean; // opcional
  className?: string;
  inputClassName?: string;
  containerClassName?: string;
  listClassName?: string;
  rowHeight?: number;                    // altura de cada linha (default 48)
  maxVirtualItems?: number;              // limite de itens virtualizados (default 500)
  bufferCount?: number;                  // buffer para estabilidade do scroll (default 8)
  readOnly?: boolean;
  autoComplete?: string;
  autoFocus?: boolean;
  style?: React.CSSProperties;
  containerStyle?: React.CSSProperties;
  inputStyle?: React.CSSProperties;
  listStyle?: React.CSSProperties;
}

// ---------------------------------------------------------------------------
// Constantes
// ---------------------------------------------------------------------------
const DEFAULT_MIN_CHARS = 2;
const DEFAULT_ROW_HEIGHT = 48;
const DEFAULT_MAX_VIRTUAL = 500;
const DEFAULT_BUFFER = 8;

function mergeClasses(base: string[], extra?: string | string[]): string {
  return [...base, ...(extra?.split(' ') || [])].filter(Boolean).join(' ');
}

function filterOptions(
  options: SelectOption<string>[],
  query: string,
  minChars: number,
): SelectOption<string>[] {
  if (query.length < minChars) return [];
  const q = query.toLowerCase();
  return options.filter((o) => {
    if (o.disabled === true) return false;
    return (o.label as string).toLowerCase().includes(q);
  });
}

// ---------------------------------------------------------------------------
// Componente principal
// ---------------------------------------------------------------------------
function DropDownInput<S extends string>({
  options,
  placeholder,
  defaultValue,
  onChange,
  onSelect,
  onClear,
  minMatchChars = DEFAULT_MIN_CHARS,
  validator,
  className,
  inputClassName,
  containerClassName,
  listClassName,
  rowHeight,
  maxVirtualItems,
  bufferCount,
  readOnly = false,
  autoComplete = 'off',
  autoFocus,
  style,
  containerStyle,
  inputStyle,
  listStyle,
}: DropDownInputProps<S>) {
  const inputId = useId();
  const listboxId = `${inputId}-listbox`;

  const inputRef = useRef<HTMLInputElement>(null!);
  const containerRef = useRef<HTMLDivElement>(null!);
  const listRef = useRef<HTMLDivElement | null>(null);
  const virtualEntriesRef = useRef<Map<number, RefObject<HTMLElement | null>>>(new Map());
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [localValue, setLocalValue] = useState<string>(defaultValue ?? '');
